True def transform(grid):
    n = len(grid)
    rot90 = [list(row) for row in zip(*grid[::-1])]
    rot180 = [row[::-1] for row in grid[::-1]]
    rot270 = [list(row) for row in zip(*grid)][::-1]
    return [
        list(grid[r]) + rot90[r]
        for r in range(n)
    ] + [
        rot270[r] + rot180[r]
        for r in range(n)
    ]
